  1	import java.util.Objects;
  2	
  3	/**
  4	 * Stable counting sort for integer arrays.
  5	 */
  6	public final class CountingSort {
  7	
  8	    private CountingSort() {
  9	    }
 10	
 11	    /**
 12	     * Legacy wrapper retained for compatibility.
 13	     */
 14	    public static int[] countSort(int[] values) {
 15	        return sortedCopy(values);
 16	    }
 17	
 18	    /**
 19	     * Legacy wrapper retained for compatibility.
 20	     */
 21	    public static int[] sort(int[] values) {
 22	        return sortedCopy(values);
 23	    }
 24	
 25	    /**
 26	     * Returns a sorted copy of {@code values}.
 27	     */
 28	    public static int[] sortedCopy(int[] values) {
 29	        Objects.requireNonNull(values, "values");
 30	        int[] sortedValues = new int[values.length];
 31	        copyInto(values, sortedValues);
 32	        return sortedValues;
 33	    }
 34	
 35	    /**
 36	     * Writes the sorted contents of {@code input} into {@code output}.
 37	     */
 38	    public static void copyInto(int[] input, int[] output) {
 39	        Objects.requireNonNull(input, "input");
 40	        Objects.requireNonNull(output, "output");
 41	        requireSameLength(input, output);
 42	
 43	        if (input.length == 0) {
 44	            return;
 45	        }
 46	
 47	        int[] source = aliasSafeInput(input, output);
 48	        CountingTable countingTable = CountingTable.from(source);
 49	        writeSortedValues(source, output, countingTable);
 50	    }
 51	
 52	    /**
 53	     * Sorts {@code values} in place.
 54	     */
 55	    public static void sortInPlace(int[] values) {
 56	        copyInto(values, values);
 57	    }
 58	
 59	    private static int[] aliasSafeInput(int[] input, int[] output) {
 60	        return input == output ? input.clone() : input;
 61	    }
 62	
 63	    private static void requireSameLength(int[] input, int[] output) {
 64	        if (input.length != output.length) {
 65	            throw new IllegalArgumentException(
 66	                "Input and output arrays must have the same length."
 67	            );
 68	        }
 69	    }
 70	
 71	    private static Range findRange(int[] values) {
 72	        int minValue = values[0];
 73	        int maxValue = values[0];
 74	
 75	        for (int i = 1; i < values.length; i++) {
 76	            int value = values[i];
 77	            if (value < minValue) {
 78	                minValue = value;
 79	            }
 80	            if (value > maxValue) {
 81	                maxValue = value;
 82	            }
 83	        }
 84	
 85	        return new Range(minValue, maxValue);
 86	    }
 87	
 88	    private static void writeSortedValues(
 89	        int[] input,
 90	        int[] output,
 91	        CountingTable countingTable
 92	    ) {
 93	        for (int i = input.length - 1; i >= 0; i--) {
 94	            int value = input[i];
 95	            output[countingTable.takeOutputIndex(value)] = value;
 96	        }
 97	    }
 98	
 99	    private record CountingTable(Range range, int[] prefixCounts) {
100	        private static CountingTable from(int[] values) {
101	            Range range = findRange(values);
102	            int[] prefixCounts = new int[range.size()];
103	
104	            for (int value : values) {
105	                prefixCounts[range.indexOf(value)]++;
106	            }
107	
108	            for (int i = 1; i < prefixCounts.length; i++) {
109	                prefixCounts[i] += prefixCounts[i - 1];
110	            }
111	
112	            return new CountingTable(range, prefixCounts);
113	        }
114	
115	        private int takeOutputIndex(int value) {
116	            int countIndex = range.indexOf(value);
117	            int outputIndex = prefixCounts[countIndex] - 1;
118	            prefixCounts[countIndex]--;
119	            return outputIndex;
120	        }
121	    }
122	
123	    private record Range(int minValue, int maxValue) {
124	        private int size() {
125	            long size = (long) maxValue - minValue + 1;
126	            if (size > Integer.MAX_VALUE) {
127	                throw new IllegalArgumentException(
128	                    "Counting sort range is too large to index."
129	                );
130	            }
131	
132	            return (int) size;
133	        }
134	
135	        private int indexOf(int value) {
136	            return value - minValue;
137	        }
138	    }
139	}

  1	import java.util.Arrays;
  2	import java.util.Random;
