  4	public final class CountingSortTest {
  5	    private static final long RANDOM_SEED = 37L;
  6	    private static final int RANDOM_CASES = 100;
  7	
  8	    private CountingSortTest() {
  9	    }
 10	
 11	    public static void main(String[] args) {
 12	        testSortedCopyHandlesEdgeCases();
 13	        testCopyIntoWritesExpectedValues();
 14	        testCopyIntoSupportsAliasedInputAndOutput();
 15	        testSortInPlaceMutatesTheInput();
 16	        testCompatibilityWrappers();
 17	        testInvalidInputs();
 18	        testRandomizedAgreementWithArraysSort();
 19	    }
 20	
 21	    private static void testSortedCopyHandlesEdgeCases() {
 22	        assertSorted(new int[] {});
 23	        assertSorted(new int[] {2, 5, 3, 0, 2, 3, 0, 3, -4, -1});
 24	        assertSorted(new int[] {7});
 25	        assertSorted(new int[] {4, 4, 4, 4});
 26	    }
 27	
 28	    private static void testCopyIntoWritesExpectedValues() {
 29	        int[] input = {3, -1, 3, 0};
 30	        int[] output = new int[input.length];
 31	
 32	        CountingSort.copyInto(input, output);
 33	
 34	        assertArrayEquals(new int[] {-1, 0, 3, 3}, output);
 35	    }
 36	
 37	    private static void testCopyIntoSupportsAliasedInputAndOutput() {
 38	        int[] values = {9, -2, 9, 1, 0};
 39	
 40	        CountingSort.copyInto(values, values);
 41	
 42	        assertArrayEquals(new int[] {-2, 0, 1, 9, 9}, values);
 43	    }
 44	
 45	    private static void testSortInPlaceMutatesTheInput() {
 46	        int[] values = {3, -1, 3, 0};
 47	
 48	        CountingSort.sortInPlace(values);
 49	
 50	        assertArrayEquals(new int[] {-1, 0, 3, 3}, values);
 51	    }
 52	
 53	    private static void testCompatibilityWrappers() {
 54	        int[] input = {5, -3, 1, 5, 0};
 55	        int[] expected = sortedWithArraysSort(input);
 56	
 57	        assertArrayEquals(expected, CountingSort.countSort(input));
 58	        assertArrayEquals(expected, CountingSort.sort(input));
 59	    }
 60	
 61	    private static void testInvalidInputs() {
 62	        assertThrows(
 63	            IllegalArgumentException.class,
 64	            () -> CountingSort.copyInto(new int[] {1, 2}, new int[1])
 65	        );
 66	        assertThrows(
 67	            NullPointerException.class,
 68	            () -> CountingSort.sortedCopy(null)
 69	        );
 70	        assertThrows(
 71	            NullPointerException.class,
 72	            () -> CountingSort.copyInto(new int[] {1, 2}, null)
 73	        );
 74	    }
 75	
 76	    private static void testRandomizedAgreementWithArraysSort() {
 77	        Random random = new Random(RANDOM_SEED);
 78	
 79	        for (int i = 0; i < RANDOM_CASES; i++) {
 80	            int length = random.nextInt(20);
 81	            int[] values = new int[length];
 82	
 83	            for (int j = 0; j < values.length; j++) {
 84	                values[j] = random.nextInt(41) - 20;
 85	            }
 86	
 87	            assertSorted(values);
 88	        }
 89	    }
 90	
 91	    private static void assertSorted(int[] values) {
 92	        int[] expected = sortedWithArraysSort(values);
 93	        assertArrayEquals(expected, CountingSort.sortedCopy(values));
 94	    }
 95	
 96	    private static int[] sortedWithArraysSort(int[] values) {
 97	        int[] expected = values.clone();
 98	        Arrays.sort(expected);
 99	        return expected;
100	    }
101	
102	    private static void assertArrayEquals(int[] expected, int[] actual) {
103	        if (!Arrays.equals(expected, actual)) {
104	            throw new AssertionError(
105	                "Expected " + Arrays.toString(expected)
106	                    + " but was " + Arrays.toString(actual)
107	            );
108	        }
109	    }
110	
111	    private static void assertThrows(
112	        Class<? extends Throwable> expectedType,
113	        ThrowingRunnable action
114	    ) {
115	        try {
116	            action.run();
117	        } catch (Throwable throwable) {
118	            if (expectedType.isInstance(throwable)) {
119	                return;
120	            }
121	
122	            throw new AssertionError(
123	                "Expected " + expectedType.getSimpleName()
124	                    + " but caught " + throwable.getClass().getSimpleName(),
125	                throwable
126	            );
127	        }
128	
129	        throw new AssertionError(
130	            "Expected " + expectedType.getSimpleName() + " to be thrown."
131	        );
132	    }
133	
134	    @FunctionalInterface
135	    private interface ThrowingRunnable {
136	        void run();
137	    }
138	}
